import {startAnimationLoop} from './vendor/pixel-agents/index.js';
import {InputState,createPlayer,updatePlayer,cameraFor,screenToWorld,worldToScreen,nearestInteractable} from './engine.js';
import {makeScene,TOPICS} from './scenes.js';
import {renderScene,renderMinimap,drawActor,COLORS} from './renderer.js';
const $=id=>document.getElementById(id),worlds=window.TASK_WORLDS||[],facts=window.TASK_WORLD_CONTENT||{},snapshot=window.TASK_WORLD_SNAPSHOT||{},originalFacts=JSON.stringify(worlds);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const statusNames={done:'阶段已交付',blocked:'条件待补',review:'已交付 · 待修',paused:'已暂停',planned:'待启动',unknown:'待核实'};
const canvas=$('world-canvas'),ctx=canvas.getContext('2d'),mini=$('minimap').getContext('2d'),input=new InputState(),images={};let scene=makeScene(worlds),player=createPlayer(scene.spawn.x,scene.spawn.y),camera=null,viewport={width:innerWidth,height:innerHeight},nearest=null,target=null,overlay=null,elapsed=0,transitioning=false,toastTimer=null,transitionTimer=null,lastInteraction=0;
const positions=new Map(),visits=new Set(),reads=new Set(),storageKey='task-world-demo-exploration';
try{let saved=JSON.parse(localStorage.getItem(storageKey)||'{}');(saved.visits||[]).forEach(x=>visits.add(x));(saved.reads||[]).forEach(x=>reads.add(x));}catch{}
function saveExploration(){try{localStorage.setItem(storageKey,JSON.stringify({visits:[...visits],reads:[...reads]}));}catch{}$('journal-count').textContent=visits.size;}
function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3600);}
function zoom(){return viewport.width<650?.88:viewport.width<1100?1:1.12;}
function resize(){viewport={width:$('game').clientWidth,height:$('game').clientHeight};const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(viewport.width*dpr);canvas.height=Math.round(viewport.height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);camera=cameraFor(player,viewport,zoom());draw();}
function dateLabel(value){if(!value)return '日期待核实';if(/^\d{4}-\d{2}-\d{2}$/.test(value))return value;try{return new Date(value).toLocaleString('zh-CN',{timeZone:'UTC',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false})}catch{return String(value)}}
function setupHUD(){const w=scene.world,n=scene.node;const level=scene.level==='world'?'第 1 层 · 世界':scene.level==='region'?'第 2 层 · 项目领地':'第 3 层 · 工位';$('level-label').textContent=level;$('place-title').textContent=scene.title;$('back-button').hidden=scene.level==='world';$('breadcrumb').innerHTML=scene.level==='world'?'六片领地 · 步行探索':`<button data-back="world">示例小岛</button><span>›</span>${scene.level==='stage'?`<button data-back="region">${esc(w.name)}</button><span>›</span>${esc(n.number+' '+n.title)}`:esc(w.number+' '+w.name)}`;
$('map-caption').textContent=scene.level==='world'?'世界 · 6 片领地':scene.level==='region'?`${w.nodes.length} 个工位 · 靠近进入`:'4 处记录 · 1 份来源';
$('snapshot-label').textContent='示例 '+dateLabel(snapshot.updatedAt||snapshot.at||snapshot.checkedAt);saveExploration();updateObjective();}
function updateObjective(){if(target){$('objective').querySelector('.eyebrow').textContent='路线提示';$('objective-title').textContent=target.label;$('objective-detail').textContent='跟随金色方向提示，沿可走区域前进。靠近后按 E。';$('clear-target').hidden=false;return;}$('clear-target').hidden=true;$('objective').querySelector('.eyebrow').textContent=scene.level==='stage'?'工位探索':scene.level==='region'?'先和负责人聊聊':'今天从这里开始';$('objective-title').textContent=scene.level==='world'?'沿石径，寻找项目路标':scene.level==='region'?scene.world.subject:scene.node.number+' · '+scene.node.title;$('objective-detail').textContent=scene.level==='world'?'方向键 / WASD 移动。路标、NPC 和工作台都要靠近才能交互。':scene.level==='region'?scene.world.summary:'先看四处记录，再查来源。你读到的是有日期的档案，不是实时任务。';}
function transition(level,worldId=null,nodeId=null,{restore=false,push=true}={}){if(transitioning&&push)return;clearTimeout(transitionTimer);positions.set(scene.id,{x:player.x,y:player.y});input.clear();target=null;nearest=null;closePanel(false);scene=makeScene(worlds,level,worldId,nodeId);let p=restore&&positions.get(scene.id)||scene.spawn;player=createPlayer(p.x,p.y);if(scene.level!=='world')visits.add(scene.id);camera=cameraFor(player,viewport,zoom());setupHUD();draw();if(push){let hash=scene.level==='world'?'world':scene.level==='region'?scene.world.id:`${scene.world.id}/${scene.node.id}`;history.pushState(null,'','#'+hash);}transitioning=true;$('scene-transition').classList.add('active');transitionTimer=setTimeout(()=>{$('scene-transition').classList.remove('active');transitioning=false;canvas.focus({preventScroll:true});},130);}
function goBack(){if(overlay){closePanel();return;}if(scene.level==='stage')transition('region',scene.world.id,null,{restore:true});else if(scene.level==='region')transition('world',null,null,{restore:true});else toast('你已经在世界地图。');}
function setTarget(id){const e=scene.entities.find(x=>x.id===id);if(!e)return;target=e;updateObjective();closePanel();toast('已标记 '+e.label+'。跟随金色方向提示。');}
function openPanel(type,html,kicker='固定档案对话'){input.clear();overlay=type;$('panel-kicker').textContent=kicker;$('panel-content').innerHTML=html;$('panel-content').scrollTop=0;document.body.classList.add('panel-open');if(!$('panel').open)$('panel').showModal();requestAnimationFrame(()=>{$('panel-content').querySelector('button')?.focus({preventScroll:true});document.querySelectorAll('.npc-portrait').forEach(c=>{const cctx=c.getContext('2d');cctx.imageSmoothingEnabled=false;cctx.clearRect(0,0,c.width,c.height);drawActor(cctx,{x:c.width/2,y:c.height-8,facing:'down'},true,scene.theme.accent);});});}
function closePanel(focus=true){if($('panel').open)$('panel').close();overlay=null;input.clear();document.body.classList.remove('panel-open');if(focus)canvas.focus({preventScroll:true});}
function npcHeader(w=scene.world,n=scene.node){return `<div class="npc-header"><canvas class="npc-portrait" width="58" height="67" aria-hidden="true"></canvas><div><h2 id="panel-title">${esc(w?.npc?.name||'领路员')}</h2><p>${esc(w?.npc?.role||'探索向导')} · <span class="status-tag">${esc(w?.npc?.execution||'固定档案')}</span></p></div></div>${n?`<p class="lead">${esc(n.number+' · '+n.title)} <span class="status-tag ${n.state}">${esc(n.short)}</span></p>`:''}`;}
const refMap=()=>Object.fromEntries((Array.isArray(facts.evidence)?facts.evidence:Object.values(facts.evidence||{})).map(e=>[e.id,e]));
function evidenceHTML(n=scene.node,w=scene.world){const refs=n?.sourceRefs||w?.sourceRefs||w?.nodes.flatMap(n=>n.sourceRefs||[])||[];let map=refMap();let unique=[...new Set(refs)];let html=unique.map(r=>typeof r==='string'?map[r]:r).filter(Boolean).map(e=>`<li>${esc(e.label||e.title||e.id)}${e.sourceDate?' · 记录 '+esc(dateLabel(e.sourceDate)):''}<br>核对：${esc(dateLabel(e.verifiedAt||e.checkedAt))} · ${esc(e.evidenceStatus||'状态待核实')}</li>`).join('');return `<div class="evidence-bar">${esc(n?.evidence||w?.npc?.executionNote||'只读档案。现场人物是岗位映射，不代表后台执行。')}<ul class="evidence-list">${html}</ul><span>浏览、对话与到访不会改变源项目。交付不等于验收；查看不等于完成。</span></div>`;}
function topicMenu(w,n){return `<div class="topic-grid">${TOPICS.map(t=>{let key=(n?.id||w.id)+':'+t.id;return `<button class="topic-button" data-topic="${t.id}"><span class="topic-icon">${t.icon}</span><span><b>${t.title}</b><small>${n?'查看这个工位':'查看本项目概况'}</small></span>${reads.has(key)?'<span class="read-mark">读过</span>':''}</button>`}).join('')}</div>`;}
function showNpc(){const w=scene.world,n=scene.node;if(!w)return showGuide();let intro=n?`“这里是${n.title}。你想先问哪一项？”`:`“欢迎来到${w.name}。我按已核对档案回答，先看哪一项？”`;openPanel('npc',`${npcHeader()}<div class="dialogue-line">${esc(intro)}</div>${topicMenu(w,n)}${n?'':`<h3>可以走进去的工位</h3><div class="room-list">${w.nodes.map(x=>`<button data-target="stage-${x.id}">${esc(x.number+' '+x.title)}<small>${esc(x.short)} · 标记路线</small></button>`).join('')}</div>`}<button class="back-link" data-evidence>查看依据与执行状态 →</button>`,'负责人岗位 · 固定树形菜单');}
function linesHTML(value){if(value==null)return '';if(typeof value==='string')return `<p>${esc(value)}</p>`;if(Array.isArray(value))return value.map(x=>typeof x==='string'?`<p>${esc(x)}</p>`:`${x.title?`<h3>${esc(x.title)}</h3>`:''}${linesHTML(x.text||x.content||x.body||x.items||JSON.stringify(x))}`).join('');return linesHTML(value.items||value.text||value.body||value.content||Object.values(value));}
function topicContent(w,n,topic){if(n?.sections?.[topic])return linesHTML(n.sections[topic]);let d=w.npc?.dialogue?.[topic];if(d)return linesHTML(d);if(!n)return w.nodes.map(x=>`<h3>${esc(x.number+' '+x.title)}</h3>${topicContent(w,x,topic)}`).join('');return linesHTML(topic==='progress'?n.detail:topic==='nextSteps'?n.next:topic==='results'?n.state==='done'?n.detail:'目前档案没有此工位已通过验收的结论。':n.state==='done'?'阶段交付与后续使用仍需区分，请参照成果记录和下一步。':n.detail);}
function showTopic(topic){const w=scene.world,n=scene.node,t=TOPICS.find(x=>x.id===topic);if(!w||!t)return;reads.add((n?.id||w.id)+':'+topic);saveExploration();let deep=(n?.conversations||[]).filter(c=>!c.topic||c.topic===topic);openPanel('topic',`<button class="back-link" data-npc>← 返回对话菜单</button>${npcHeader()}<h3>${t.title}</h3>${topicContent(w,n,topic)}${deep.length?`<h3>继续追问</h3><div class="room-list">${deep.map((c,i)=>`<button data-conversation="${(n.conversations||[]).indexOf(c)}">${esc(c.question||c.title||'进一步查看')}<small>固定档案说明</small></button>`).join('')}</div>`:''}${evidenceHTML(n,w)}`,'档案对话 / '+t.title);}
function showConversation(i){const n=scene.node,c=n?.conversations?.[i];if(!c)return;reads.add(n.id+':conversation-'+i);saveExploration();openPanel('conversation',`<button class="back-link" data-npc>← 返回对话菜单</button>${npcHeader()}<h3>${esc(c.question||c.title)}</h3>${linesHTML(c.answer||c.content||c.text||c.paragraphs)}${evidenceHTML()}`,'继续追问 · 固定档案');}
function showEvidence(){if(!scene.world)return showSources();openPanel('evidence',`<button class="back-link" data-npc>← 返回对话菜单</button><h2 id="panel-title">来源档案</h2><p class="lead">${esc(scene.node?.title||scene.world.subject)}</p><p>${esc(scene.world.npc?.executionNote||'负责人按岗位呈现；没有证据的活动状态不会推断为正在执行。')}</p>${evidenceHTML()}`,'证据与时间');}
function showGuide(){openPanel('guide',`${npcHeader(null,null)}<div class="dialogue-line">“这里每条路都通向虚构的示例项目。散步、交谈、读档案，按自己的节奏走。”</div><div class="topic-grid"><button class="topic-button" data-help><span class="topic-icon">走</span><span><b>怎么探索</b><small>移动、交互和层级</small></span></button><button class="topic-button" data-map><span class="topic-icon">览</span><span><b>各领地有什么</b><small>项目导览与路线提示</small></span></button><button class="topic-button" data-journal><span class="topic-icon">记</span><span><b>我读到哪里了</b><small>仅保存本机游历</small></span></button><button class="topic-button" data-sources><span class="topic-icon">证</span><span><b>这些状态可靠吗</b><small>只读快照与证据</small></span></button></div>`,'星球领路员');}
function showHelp(){openPanel('help',`<h2 id="panel-title">慢慢走，看看近况。</h2><p class="lead">角色始终在画面中心。世界比屏幕更大，镜头会随着脚步移动。</p><dl class="help-grid"><dt>方向键 / WASD</dt><dd>四向移动。可以同时按两方向斜走，速度保持一致。</dd><dt>E / Enter</dt><dd>靠近路标进区域，靠近 NPC 或工作台打开固定对话。</dd><dt>Esc</dt><dd>先关闭对话，再从工位退回大厅，从大厅退回世界。</dd><dt>M / J</dt><dd>打开导览 / 手记。导览只标记方向，仍需要自己走过去。</dd><dt>鼠标点选</dt><dd>近处可以直接交互；远处只设路线提示。墙、家具和岛外不可穿越。</dd><dt>手机触屏</dt><dd>按住左下方向键行走，右下按钮交互。松开、切屏就停止。</dd></dl><h3>三层世界</h3><p>世界有 6 片领地。进入领地后，沿编号路标去具体工位。每个工位有进度记录板、成果陈列台、条件检查台、下一步路线桌和来源档案，还能找负责人岗位 NPC 继续追问。</p><h3>你的手记</h3><p>到访与阅读会保存在这个浏览器。它们只帮助你接着探索，不会把源项目标为完成，也不会启动、授权或排程任务。</p><p>没有收集奖励、倒计时或虚构进度。所有内容均为固定的虚构示例，不代表真实活动。</p>`,'操作说明');}
function showMap(){let es=scene.entities.filter(e=>['portal','stage','topic','npc','evidence'].includes(e.type));openPanel('map',`<h2 id="panel-title">${esc(scene.title)} · 导览</h2><p class="lead">选择目的地设置方向提示，沿路步行过去。</p><canvas id="overview-canvas" class="map-overview" width="700" height="${Math.round(700*scene.height/scene.width)}"></canvas>${es.map(e=>`<div class="entry-row"><span class="entry-number">${esc(e.number||'◇')}</span><div class="entry-copy"><strong>${esc(e.label)}</strong><p>${esc(e.subtitle||e.role||'靠近后交互')}</p></div><button data-target="${e.id}">指路</button></div>`).join('')}<p class="evidence-bar">路线提示不会自动绕行。实际通行受岛岸、墙面、家具限制。</p>`,'漫游导览');requestAnimationFrame(()=>{const c=$('overview-canvas');if(!c)return;renderMinimap(c.getContext('2d'),scene,player,images,visits,target);});}
function showJournal(){let stageCount=worlds.reduce((s,w)=>s+w.nodes.length,0),seen=worlds.flatMap(w=>w.nodes).filter(n=>visits.has(n.id)).length,topicCount=[...reads].filter(x=>!x.includes(':conversation-')).length;openPanel('journal',`<h2 id="panel-title">我的探索手记</h2><p class="lead">今天想去哪里，看到哪里，就记到哪里。</p><div class="journal-summary"><div><b>${seen}<span style="font-size:15px;color:#9aaa8c"> / ${stageCount}</span></b><small>到访工位</small></div><div><b>${topicCount}</b><small>已读档案主题</small></div><div><b>${worlds.filter(w=>visits.has(w.id)).length}<span style="font-size:15px;color:#9aaa8c"> / 6</span></b><small>到访领地</small></div></div>${worlds.map(w=>`<h3>${esc(w.number+' '+w.name)} <span class="status-tag ${w.state}">${esc(w.label)}</span></h3>${w.nodes.map(n=>`<div class="entry-row"><span class="entry-number">${esc(n.number)}</span><div class="entry-copy"><strong>${esc(n.title)}</strong><p>${visits.has(n.id)?'已到访':'还没走到'} · 阅读 ${TOPICS.filter(t=>reads.has(n.id+':'+t.id)).length} / 4 主题</p></div><span class="status-tag ${n.state}">${esc(n.short)}</span></div>`).join('')}`).join('')}<p class="evidence-bar">本机个人游历记录，不同步源项目，不计作任务完成。项目状态仍以各工位注明的证据为准。</p>`,'旅途记录 · 与任务状态分开');}
function showSources(){let es=Array.isArray(facts.evidence)?facts.evidence:Object.values(facts.evidence||{});openPanel('sources',`<h2 id="panel-title">虚构示例，静态世界。</h2><p class="lead">这是数小时探索产生的未完成原型，已暂停开发。</p><p>所有项目名称、角色、阶段、日期、状态和记录均为合成示例，没有接入个人资料或真实项目。</p><h3>示例说明</h3>${es.map(e=>`<div class="source-row">${esc(e.label)}<small>${esc(e.evidenceStatus)}</small></div>`).join('')}<h3>边界</h3><p>这是固定对话与本机游历记录。角色动画不会启动任务，状态颜色不代表真实交付。交互体验仍有缺口，尚未完成真实浏览器、触屏和跨端验收。</p><h3>素材与技术</h3><p>背景为 AI 生成的原创通用场景，人物由项目内像素数组绘制。动画循环、像素缓存与深度排序改编自 Pixel Agents 的 MIT 许可版本；未使用上游图片或字体。</p><p><a href="vendor/pixel-agents/LICENSE" target="_blank" rel="noopener">MIT 许可</a> · <a href="https://github.com/pixel-agents-hq/pixel-agents/tree/d1e007a9fdf3003c252d2973abe1999ae59aec33" target="_blank" rel="noopener">上游固定版本</a></p>`,'未完成 · 合成示例');}
function interact(entity=nearest){if(!entity||overlay||transitioning||performance.now()-lastInteraction<220)return;if(Math.hypot(player.x-entity.x,player.y-entity.y)>88){setTarget(entity.id);return;}lastInteraction=performance.now();input.clear();target=null;updateObjective();switch(entity.type){case'portal':transition('region',entity.worldId);break;case'stage':transition('stage',scene.world.id,entity.nodeId);break;case'npc':showNpc();break;case'guide':showGuide();break;case'topic':showTopic(entity.topic);break;case'evidence':showEvidence();break;case'exit':goBack();break;}}
function draw(){if(!camera)return;renderScene(ctx,{scene,player,camera,images,nearest,time:elapsed,visited:visits,target});renderMinimap(mini,scene,player,images,visits,target);}
function update(dt){elapsed+=dt;updatePlayer(player,input,dt,scene,Boolean(overlay||transitioning));camera=cameraFor(player,viewport,zoom());nearest=nearestInteractable(player,scene.entities,84);$('interaction-prompt').hidden=!nearest||Boolean(overlay||transitioning);if(nearest)$('interaction-prompt').querySelector('span').textContent=nearest.type==='portal'?'进入 '+nearest.label:nearest.type==='stage'?'进入 '+nearest.number+' '+nearest.label:nearest.type==='npc'?'与 '+nearest.label+' 交谈':nearest.label;if(target&&Math.hypot(target.x-player.x,target.y-player.y)<84){target=null;updateObjective();}if(input.consumeInteract())interact();}
input.bind(window);window.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();if(e.repeat)return;if(overlay)closePanel();else goBack();return;}if(overlay)return;if(e.repeat)return;if(e.key.toLowerCase()==='m'){e.preventDefault();showMap();}if(e.key.toLowerCase()==='j'){e.preventDefault();showJournal();}});
canvas.addEventListener('pointerdown',e=>{if(overlay)return;canvas.focus({preventScroll:true});let r=canvas.getBoundingClientRect(),p=screenToWorld({x:e.clientX-r.left,y:e.clientY-r.top},camera);let entity=[...scene.entities].sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y)).find(a=>Math.abs(a.x-p.x)<100&&p.y>a.y-155&&p.y<a.y+40);if(entity){if(Math.hypot(player.x-entity.x,player.y-entity.y)<=88)interact(entity);else setTarget(entity.id);}});
document.querySelectorAll('[data-dir]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();if(overlay)return;b.setPointerCapture(e.pointerId);b.classList.add('active');input.pointerDown(e.pointerId,b.dataset.dir);});const release=e=>{b.classList.remove('active');input.pointerUp(e.pointerId);};b.addEventListener('pointerup',release);b.addEventListener('pointercancel',release);b.addEventListener('lostpointercapture',release);});
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.target)return setTarget(b.dataset.target);if(b.dataset.topic)return showTopic(b.dataset.topic);if(b.hasAttribute('data-npc'))return showNpc();if(b.hasAttribute('data-evidence'))return showEvidence();if(b.hasAttribute('data-conversation'))return showConversation(Number(b.dataset.conversation));if(b.hasAttribute('data-help'))return showHelp();if(b.hasAttribute('data-map'))return showMap();if(b.hasAttribute('data-journal'))return showJournal();if(b.hasAttribute('data-sources'))return showSources();if(b.dataset.back==='world')return transition('world',null,null,{restore:true});if(b.dataset.back==='region')return transition('region',scene.world.id,null,{restore:true});});
$('panel').addEventListener('cancel',e=>{e.preventDefault();closePanel();});$('panel').addEventListener('close',()=>{overlay=null;input.clear();document.body.classList.remove('panel-open');});$('panel-close').onclick=()=>closePanel();$('back-button').onclick=goBack;$('help-button').onclick=showHelp;$('journal-button').onclick=showJournal;$('map-button').onclick=showMap;$('sources-button').onclick=showSources;$('clear-target').onclick=()=>{target=null;updateObjective();};$('interaction-prompt').onclick=()=>interact();$('fullscreen-button').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('game').requestFullscreen();}catch{toast('当前浏览器未允许全屏，仍可在当前画面探索。');}};
window.addEventListener('resize',resize);window.addEventListener('blur',()=>document.querySelectorAll('[data-dir]').forEach(b=>b.classList.remove('active')));window.addEventListener('popstate',()=>{let [w,n]=location.hash.slice(1).split('/');transition(!w||w==='world'?'world':n?'stage':'region',w,n,{restore:true,push:false});});
for(let src of ['assets/island.png','assets/workshop.png','assets/studio.png','assets/archive.png']){const i=new Image();i.onload=()=>{images[src]=i;draw();};i.src=src;}
setupHUD();resize();const initial=location.hash.slice(1).split('/');if(initial[0]&&initial[0]!=='world')transition(initial[1]?'stage':'region',initial[0],initial[1],{push:false});
let stopLoop=startAnimationLoop(update,draw),loopStopped=false;window.addEventListener('pagehide',()=>{stopLoop();loopStopped=true;input.clear();});window.addEventListener('pageshow',()=>{if(loopStopped){stopLoop=startAnimationLoop(update,draw);loopStopped=false;input.clear();resize();}});
window.TASK_WORLD_VIEW={getState:()=>({level:scene.level,world:scene.world?.id||'world',node:scene.node?.id||null,player:{...player},camera:{...camera},overlay,nearest:nearest?.id||null,target:target?.id||null,snapshotUnchanged:JSON.stringify(worlds)===originalFacts,visits:[...visits],reads:[...reads]}),enter:(id)=>transition('region',id),stage:(id,n)=>transition('stage',id,n),overview:()=>transition('world'),back:goBack,showNpc,showTopic,closePanel,interact,update,render:draw,scene:()=>scene,input,screenToWorld:p=>screenToWorld(p,camera),worldToScreen:p=>worldToScreen(p,camera)};
